import { describe, expect, it } from 'vitest'
import { deepgramEvents, speakerNumber } from './speakerTurns'
import { mergeSegments, transcriptText, sanitizeSegments, type Segment } from '@/lib/transcript/store'
const result = (final: boolean, transcript = 'Hello. Hi. Welcome.') => ({ is_final: final, start: 1, duration: 3,
  channel: { alternatives: [{ transcript, words: [
    { punctuated_word: 'Hello.', speaker: 0, start: 1, end: 1.5 },
    { punctuated_word: 'Hi.', speaker: 1, start: 2, end: 2.5 },
    { punctuated_word: 'Welcome.', speaker: 0, start: 3, end: 4 },
  ] }] } })
describe('word-level diarization', () => {
  it('retains every speaker change, including a returning speaker', () => {
    expect(deepgramEvents(result(true)).map(row => [row.speaker, row.text, row.startMs])).toEqual([[0, 'Hello.', 1000], [1, 'Hi.', 2000], [0, 'Welcome.', 3000]])
  })
  it('keeps interims replaceable and replaces them with all final turns exactly once', () => {
    let rows: Segment[] = []
    for (const event of deepgramEvents(result(false))) rows = mergeSegments(rows, event)
    expect(rows).toHaveLength(1); expect(rows[0].speaker).toBeNull()
    for (const event of deepgramEvents(result(true))) rows = mergeSegments(rows, event)
    expect(rows).toHaveLength(3)
    expect(transcriptText(rows)).toBe('Speaker 1: Hello.\nSpeaker 2: Hi.\nSpeaker 1: Welcome.')
  })
  it('preserves canonical formatted text rather than losing it on a word mismatch', () => {
    expect(deepgramEvents(result(true, 'A differently formatted $12.50.'))).toEqual([expect.objectContaining({ text: 'A differently formatted $12.50.', speaker: null })])
  })
  it('preserves an unknown speaker rather than assigning the adjacent voice', () => {
    const data = result(true); Object.assign(data.channel.alternatives[0].words[1], { speaker: undefined })
    expect(deepgramEvents(data).map(row => row.speaker)).toEqual([0, null, 0])
  })
  it('rejects non-finite and invalid labels', () => {
    for (const value of [-1, .5, NaN, Infinity, '0', null, 1000]) expect(speakerNumber(value)).toBeNull()
    expect(speakerNumber(0)).toBe(0)
    expect(sanitizeSegments([{ speaker: Infinity, text: 'hi' }])[0].speaker).toBeNull()
  })
  it('ignores malformed frames and retains text with no word metadata', () => {
    expect(deepgramEvents(null)).toEqual([])
    expect(deepgramEvents({ channel: { alternatives: [{ transcript: 'Still audible' }] } })[0]).toMatchObject({ text: 'Still audible', speaker: null })
  })
  it('exports user-assigned speaker names without inventing identity', () => {
    expect(transcriptText([{ id: 1, name: 'Martin', speaker: 0, text: 'Hello', isFinal: true }])).toBe('Martin: Hello')
  })
})

import type { TranscriptEvent } from './types'

export type SpeakerWord = { text: string; speaker: number | null; startMs: number; endMs: number }
export function speakerNumber(value: unknown): number | null {
  return typeof value === 'number' && Number.isInteger(value) && value >= 0 && value < 1000 ? value : null
}
const normalized = (text: string) => text.replace(/\s+/g, ' ').trim()
const time = (value: unknown, fallback: number) => typeof value === 'number' && Number.isFinite(value) && value >= 0 ? value : fallback
const object = (value: unknown): Record<string, unknown> => value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : {}

/** Only finalized words are split. An interim remains one replaceable hypothesis;
 * otherwise every ASR revision would append phantom speaker turns. If provider
 * formatting cannot be aligned, retain all canonical text and mark mixed speech
 * unknown rather than inventing an attribution or dropping words. */
export function splitSpeakerTurns(event: TranscriptEvent, words: SpeakerWord[]): TranscriptEvent[] {
  if (!words.length) return [event]
  const speakers = new Set(words.map(word => word.speaker))
  const common = speakers.size === 1 ? words[0].speaker : null
  if (!event.isFinal || words.some(word => !word.text.trim()) || normalized(words.map(word => word.text).join(' ')) !== normalized(event.text)) {
    return [{ ...event, speaker: common }]
  }
  const turns: TranscriptEvent[] = []
  for (const word of words) {
    const last = turns.at(-1)
    if (last && last.speaker === word.speaker) {
      last.text += ` ${word.text.trim()}`
      last.endMs = Math.max(last.endMs, word.endMs)
    } else {
      turns.push({ text: word.text.trim(), speaker: word.speaker, isFinal: true,
        startMs: word.startMs, endMs: Math.max(word.startMs, word.endMs) })
    }
  }
  return turns
}

export function deepgramEvents(input: unknown): TranscriptEvent[] {
  const data = object(input)
  const alternatives = object(data.channel).alternatives
  const alt = object(Array.isArray(alternatives) ? alternatives[0] : null)
  if (typeof alt.transcript !== 'string' || !alt.transcript.trim()) return []
  const start = time(data.start, 0) * 1000
  const end = start + time(data.duration, 0) * 1000
  const words: SpeakerWord[] = (Array.isArray(alt.words) ? alt.words : []).map(value => {
    const word = object(value)
    return { text: typeof word.punctuated_word === 'string' ? word.punctuated_word : typeof word.word === 'string' ? word.word : '',
      speaker: speakerNumber(word.speaker), startMs: Math.round(time(word.start, start / 1000) * 1000),
      endMs: Math.round(time(word.end, end / 1000) * 1000) }
  })
  return splitSpeakerTurns({ text: alt.transcript, isFinal: data.is_final === true,
    speaker: words[0]?.speaker ?? null, startMs: words[0]?.startMs ?? Math.round(start),
    endMs: words.at(-1)?.endMs ?? Math.round(end) }, words)
}

// Responsive UI smoke checks in a local development server. No real call or
// provider request is made; this is not a live speech/model accuracy evaluation.
import { createRequire } from 'node:module'
import { mkdir, writeFile } from 'node:fs/promises'
import assert from 'node:assert/strict'
const require = createRequire(import.meta.url)
const { chromium } = require(process.env.PLAYWRIGHT_PACKAGE || '/tmp/lt-browser/node_modules/playwright')
const base = process.env.UI_TEST_URL || 'http://127.0.0.1:3100'
if (!['localhost', '127.0.0.1'].includes(new URL(base).hostname)) throw new Error('Browser fixture checks require a local development server')
await mkdir('test-results/calls-ui', { recursive: true })
const browser = await chromium.launch({ headless: true })
const results = []
try {
  for (const [width, height] of [[390, 844], [768, 1024], [1440, 1000]]) {
    const context = await browser.newContext({ viewport: { width, height }, colorScheme: 'light', reducedMotion: 'reduce' })
    const page = await context.newPage()
    const errors = []
    page.on('pageerror', error => errors.push(error.message))
    // Fails the run if an accidental capture action tries to start a paid stream.
    let tokenCalls = 0
    await page.route('**/api/token', route => { tokenCalls++; return route.fulfill({ status: 503, body: JSON.stringify({ error: 'UI test: no speech provider' }) }) })
    await page.goto(`${base}/interview`, { waitUntil: 'networkidle', timeout: 90000 })
    await page.getByRole('tablist', { name: 'Interview views' }).waitFor()
    assert.equal(await page.getByRole('tab').count(), 3)
    assert.equal(await page.evaluate(() => getComputedStyle(document.documentElement).getPropertyValue('--paper').trim()), '#faf9f7')
    assert.equal(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth + 1), true, `horizontal overflow at ${width}`)
    if (width < 1024) await page.getByLabel('Open workspace navigation').click()
    const navigation = page.getByRole('navigation', { name: width < 1024 ? 'Mobile workspace' : 'Workspace', exact: true })
    assert.equal(await navigation.getByRole('link', { name: 'Interviews', exact: true }).count(), 1)
    assert.equal(await navigation.getByRole('link', { name: 'Repository', exact: true }).count(), 0)
    assert.equal(await navigation.getByRole('link', { name: 'Mock Lab', exact: true }).count(), 0)
    if (width < 1024) await page.keyboard.press('Escape')
    await page.getByRole('tab', { name: 'Mock Lab', exact: true }).click()
    await page.getByRole('tab', { name: 'Live interview', exact: true }).click()
    await page.getByLabel('Call service', { exact: true }).selectOption('google-voice')
    await page.getByRole('link', { name: 'Open Google Voice' }).waitFor()
    assert.equal(await page.getByRole('button', { name: 'Start interview', exact: true }).isDisabled(), true)
    await page.getByRole('checkbox', { name: /I have permission/ }).check()
    assert.equal(await page.getByRole('button', { name: 'Start interview', exact: true }).isEnabled(), true)
    assert.equal(tokenCalls, 0)
    assert.equal(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth + 1), true)
    await page.screenshot({ path: `test-results/calls-ui/voice-${width}-light.png`, fullPage: true })
    await page.getByRole('button', { name: 'Switch to dark mode', exact: true }).click()
    assert.equal(await page.evaluate(() => getComputedStyle(document.documentElement).getPropertyValue('--paper').trim()), '#121216')
    await page.screenshot({ path: `test-results/calls-ui/voice-${width}-dark.png`, fullPage: true })
    assert.deepEqual(errors, [])
    results.push({ width, height, lightAndDark: true, noHorizontalOverflow: true, singleNavigation: true, googleVoiceSetup: true, consentGated: true, liveProviderCalls: tokenCalls, errors })
    await context.close()
  }
} finally {
  await writeFile('test-results/calls-ui/summary.json', JSON.stringify({ kind: 'local UI only; no physical call or AI quality claim', results }, null, 2))
  await browser.close()
}
